import '../../domain/entities/teacher_attendance_entity.dart';
class TeacherAttendanceModel extends TeacherAttendanceEntity { const TeacherAttendanceModel({required super.id,required super.teacherId,required super.teacherName,required super.attendanceDate,required super.status,required super.remarks,required super.createdAt,required super.updatedAt}); factory TeacherAttendanceModel.fromMap(Map<String,dynamic> map) => TeacherAttendanceModel(id: map['id']??'',teacherId:map['teacherId']??'',teacherName:map['teacherName']??'',attendanceDate:DateTime.parse(map['attendanceDate']),status:TeacherAttendanceStatus.values.firstWhere((value)=>value.name==map['status'],orElse:()=>TeacherAttendanceStatus.present),remarks:map['remarks']??'',createdAt:DateTime.parse(map['createdAt']),updatedAt:DateTime.parse(map['updatedAt'])); factory TeacherAttendanceModel.fromEntity(TeacherAttendanceEntity value)=>TeacherAttendanceModel(id:value.id,teacherId:value.teacherId,teacherName:value.teacherName,attendanceDate:value.attendanceDate,status:value.status,remarks:value.remarks,createdAt:value.createdAt,updatedAt:value.updatedAt); Map<String,dynamic> toMap()=>{'id':id,'teacherId':teacherId,'teacherName':teacherName,'attendanceDate':attendanceDate.toIso8601String(),'status':status.name,'remarks':remarks,'createdAt':createdAt.toIso8601String(),'updatedAt':updatedAt.toIso8601String()}; }
